#!/usr/bin/env node
// Built-in soundboard clips, generated by the ElevenLabs sound effects API
// (POST /v1/sound-generation) from the prompts below, then trimmed and leveled with ffmpeg:
// leading/trailing silence under -50 dBFS removed, gain to an RMS of -16 dBFS capped so the peak
// stays at or below -1 dBFS, mono 44.1 kHz MP3 at 96 kbit/s. Generation is not deterministic;
// rerunning replaces the clips. Prints each clip's duration for src/services/soundboard/sounds.ts.
//
//   ELEVENLABS_API_KEY=... node scripts/generate-soundboard-sounds.mjs [key ...]

import { execFileSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const OUT_DIR = join(dirname(fileURLToPath(import.meta.url)), '..', 'public', 'assets', 'sounds', 'soundboard');
const API = 'https://api.elevenlabs.io/v1/sound-generation?output_format=mp3_44100_128';
const MODEL = 'eleven_text_to_sound_v2';

/** seconds: requested length, 0.5-30. influence: prompt adherence, 0-1. */
const CLIPS = [
  { key: 'ding', seconds: 1.5, influence: 0.6, text: 'A single bright hotel service bell ding, clean metallic ring with a short natural decay, no background noise' },
  { key: 'tada', seconds: 2, influence: 0.6, text: 'Short triumphant "ta-da" fanfare played by a small brass section, celebratory reveal, ends with a held bright chord' },
  { key: 'rimshot', seconds: 1.6, influence: 0.7, text: 'Classic comedy rimshot "ba dum tss": two snare drum hits followed by a crash cymbal, live drum kit, dry room' },
  { key: 'sad-trombone', seconds: 3, influence: 0.7, text: 'Comedic sad trombone "wah wah wah wahhh", four descending notes, the last one long with a wobbly vibrato, solo trombone' },
  { key: 'boing', seconds: 1, influence: 0.6, text: 'Cartoon spring boing, a bouncy metal spring twang with a quick pitch wobble, playful' },
  { key: 'whoosh', seconds: 1, influence: 0.5, text: 'Fast airy whoosh swoosh passing by, clean transition sound effect, no impact' },
  { key: 'airhorn', seconds: 2, influence: 0.6, text: 'Loud stadium air horn, three quick blasts, celebratory party horn' },
  { key: 'crickets', seconds: 3, influence: 0.5, text: 'Awkward silence: a few crickets chirping slowly in a quiet night, nothing else' },
  { key: 'golf-clap', seconds: 2.5, influence: 0.5, text: 'A small polite golf clap, three or four people clapping softly and slowly, quiet outdoor ambience' },
  { key: 'quack', seconds: 0.8, influence: 0.7, text: 'One single clear duck quack, close up, no background' },
];

// 3 ms fade in, 30 ms fade out: a trimmed clip neither starts nor stops on a click.
const EDGES = 'afade=t=in:d=0.003,areverse,afade=t=in:d=0.03,areverse';
const SILENCE = 'silenceremove=start_periods=1:start_threshold=-50dB:start_silence=0.02,'
  + 'areverse,silenceremove=start_periods=1:start_threshold=-50dB:start_silence=0.05,areverse';

function ffmpeg(args) {
  return execFileSync('ffmpeg', ['-hide_banner', '-nostats', '-y', ...args], { stdio: ['ignore', 'pipe', 'pipe'] });
}

/** Mean and max volume in dBFS after the silence trim. */
function measure(file) {
  const out = execFileSync('sh', ['-c', `ffmpeg -hide_banner -nostats -i "$1" -af "${SILENCE},volumedetect" -f null - 2>&1`, 'sh', file], {
    encoding: 'utf8',
  });
  const mean = Number(/mean_volume: (-?[\d.]+) dB/.exec(out)?.[1]);
  const max = Number(/max_volume: (-?[\d.]+) dB/.exec(out)?.[1]);
  if (!Number.isFinite(mean) || !Number.isFinite(max)) throw new Error(`no levels for ${file}`);
  return { mean, max };
}

function duration(file) {
  const out = execFileSync('ffprobe', ['-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', file], {
    encoding: 'utf8',
  });
  return Math.round(Number(out.trim()) * 1000);
}

async function generate(clip, key) {
  const response = await fetch(API, {
    method: 'POST',
    headers: { 'xi-api-key': key, 'Content-Type': 'application/json', Accept: 'audio/mpeg' },
    body: JSON.stringify({
      text: clip.text,
      duration_seconds: clip.seconds,
      prompt_influence: clip.influence,
      model_id: MODEL,
    }),
  });
  if (!response.ok) {
    throw new Error(`${clip.key}: HTTP ${response.status} ${(await response.text()).slice(0, 300)}`);
  }
  return Buffer.from(await response.arrayBuffer());
}

async function main() {
  const key = process.env.ELEVENLABS_API_KEY;
  if (!key) throw new Error('ELEVENLABS_API_KEY is not set');
  const only = new Set(process.argv.slice(2));
  const work = mkdtempSync(join(tmpdir(), 'soundboard-'));
  try {
    for (const clip of CLIPS) {
      if (only.size && !only.has(clip.key)) continue;
      const raw = join(work, `${clip.key}.raw.mp3`);
      writeFileSync(raw, await generate(clip, key));
      const { mean, max } = measure(raw);
      const gain = Math.min(-16 - mean, -1 - max);
      const out = join(OUT_DIR, `${clip.key}.mp3`);
      ffmpeg([
        '-i', raw,
        '-af', `${SILENCE},volume=${gain.toFixed(2)}dB,${EDGES}`,
        '-ac', '1', '-ar', '44100', '-c:a', 'libmp3lame', '-b:a', '96k', '-map_metadata', '-1', out,
      ]);
      console.log(`${clip.key}: ${duration(out)} ms (gain ${gain.toFixed(1)} dB)`);
    }
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}

await main();
